DELETE FROM oa_consumable_request_item WHERE tenant_id = #{tenantId} AND request_id = #{requestId}
    AND issued_quantity = 0 AND returned_quantity = 0
    AND EXISTS(SELECT 1 FROM oa_consumable_request request
        WHERE request.tenant_id = #{tenantId} AND request.request_id = #{requestId}
            AND request.deleted = 0 AND request.status IN ('DRAFT', 'REJECTED'))
